	INSERT INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('1', 'actor_image_front', 'Actor front image prompt', 'Default front-facing actor prompt', 'Visual style: {{ visual_style }}\nPicture style: {{ style }}\n\nHigh-quality cinematic {{ visual_style }} portrait photography, ultra-detailed professional actor headshot / character portrait:\nActor name: {{ name }}\nActor description: {{ description }}\nIf the description does not explicitly specify gender, infer gender presentation from the actor name and keep it consistent. For conventionally feminine names, portray a woman / female-presenting adult; for conventionally masculine names, portray a man / male-presenting adult. Do not contradict explicit gender cues in the description.\n\nCamera direction: front view\nImage requirements:\n- Ultra-high detail, 8k resolution, extreme sharpness and texture\n- Cinematic shallow depth of field, f/1.4 aperture, natural and obvious background bokeh\n- Professional commercial portrait photography style plus contemporary cinematic still texture\n- Natural vivid expression, strong story feeling and character immersion\n- Excellent composition using rule of thirds or golden ratio\n- Closely match the {{ visual_style }} visual language and the overall {{ style }} atmosphere with high style consistency\n\nNegative prompt (strong negatives):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if "anime" in visual_style.lower() -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}\n{%- if "ancient" in style.lower() or "period" in style.lower() -%}\nmodern clothing, modern background, contemporary elements\n{%- endif -%}', '["name", "description", "visual_style", "style", "base_negative"]', '2026-03-17 06:38:57', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('2', 'actor_image_other', 'Actor side/back image prompt', 'Actor non-front view prompt', 'Visual style: {{ visual_style }}\nPicture style: {{ style }}\n\nHighly consistent identity-preserving portrait of the exact same person as the reference image: 100% identity consistency, same facial structure, same hairstyle, same clothing, same makeup, same age and base expression.\nSwitch the view completely to: {{ view_angle }}. Show the same person from this angle with correct perspective and silhouette, natural head direction for the view, no leftover front-facing elements, and no facial distortion.\nActor pose: standing upright in a neutral pose\n{{ extra_details }}\nImage requirements:\n- Ultra-high detail, 8k resolution, extreme sharpness and texture\n- Cinematic shallow depth of field, f/1.4 aperture, natural and obvious background bokeh\n- Professional commercial portrait photography style plus contemporary cinematic still texture\n- Natural vivid expression, strong story feeling and character immersion\n- Excellent composition using rule of thirds or golden ratio\n- Closely match the {{ visual_style }} visual language and the overall {{ style }} atmosphere with high style consistency\n\nNegative prompt (strong negatives):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if "anime" in visual_style.lower() -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}\n{%- if "ancient" in style.lower() or "period" in style.lower() -%}\nmodern clothing, modern background, contemporary elements\n{%- endif -%}', '["view_angle", "extra_details", "visual_style", "style", "base_negative"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('3', 'character_image_front', 'Character front image prompt', 'Character front image prompt', 'Visual style: {{ visual_style }}\nPicture style: {{ style }}\n\nHighly consistent identity-preserving portrait of the exact same person as reference image 1: 100% identity consistency, same facial structure, same hairstyle, same makeup, same age and base expression. If reference image 2 exists, use the outfit from reference image 2.\nActor pose: standing upright in a neutral pose\n{{ extra_details }}\nImage requirements:\n- Ultra-high detail, 8k resolution, extreme sharpness and texture\n- Cinematic shallow depth of field, f/1.4 aperture, natural and obvious background bokeh\n- Professional commercial portrait photography style plus contemporary cinematic still texture\n- Natural vivid expression, strong story feeling and character immersion\n- Excellent composition using rule of thirds or golden ratio\n- Closely match the {{ visual_style }} visual language and the overall {{ style }} atmosphere with high style consistency\n\nNegative prompt (strong negatives):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if "anime" in visual_style.lower() -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}\n{%- if "ancient" in style.lower() or "period" in style.lower() -%}\nmodern clothing, modern background, contemporary elements\n{%- endif -%}', '["extra_details", "visual_style", "style", "base_negative"]', '2026-03-19 09:00:34', '2026-03-30 16:00:00', 0, 0);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('4', 'prop_image_front', 'Prop image prompt', 'High-quality prop close-up', 'Visual style: {{ visual_style }}\nPicture style: {{ style }}\n\nHigh-quality cinematic {{ visual_style }} product photography / prop close-up with ultra-detailed realistic material quality:\n{{ description }}\nCamera direction: {{ view }}, classic product or prop photography angle\n{{ extra_details }}\nImage requirements:\n- Ultra-high detail, 8k resolution, extreme sharpness and texture\n- Cinematic shallow depth of field, f/1.4 or f/2.8, obvious background bokeh\n- Professional commercial product photography style plus contemporary cinematic prop texture\n- Real material rendering with clear metal reflections, leather texture, glass refraction, and fabric fibers\n- Excellent composition using rule of thirds, symmetry, or centered composition\n- Closely match the {{ visual_style }} visual language and the overall {{ style }} atmosphere with high style consistency\n\nNegative prompt (strong negatives):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if "anime" in visual_style.lower() -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}', '["description", "view", "extra_details", "visual_style", "style", "base_negative"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('5', 'scene_image_front', 'Scene image prompt', 'High-quality cinematic scene', 'Visual style: {{ visual_style }}\nPicture style: {{ style }}\n\nHigh-quality cinematic {{ visual_style }} scene image with ultra-detailed environment and atmosphere:\n{{ description }}\nCamera direction: {{ view }}\nMain subject position: center of the frame\n{{ extra_details }}\nImage requirements:\n- Ultra-high detail, 8k resolution, extreme sharpness and texture\n- Cinematic depth of field, f/2.8 to f/5.6, rich visual layering\n- Professional cinematic scene photography style plus contemporary still-frame texture\n- Realistic light, shadow, and atmosphere with clear light direction and natural particles, mist, rain streaks, or bokeh\n- Excellent composition with strong leading lines, depth, and clear foreground/midground/background layers\n- Closely match the {{ visual_style }} visual language and the overall {{ style }} atmosphere with high style consistency\n\nNegative prompt (strong negatives):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if "anime" in visual_style.lower() -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}', '["description", "view", "extra_details", "visual_style", "style", "base_negative"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
	INSERT IGNORE INTO `prompt_templates` (`id`, `category`, `name`, `preview`, `content`, `variables`, `created_at`, `updated_at`, `is_system`, `is_default`)
	VALUES
		('6', 'costume_image_front', 'Costume image prompt', 'High-quality costume presentation', 'Visual style: {{ visual_style }}\nPicture style: {{ style }}\n\nHigh-quality cinematic {{ visual_style }} costume close-up / full-body outfit presentation with ultra-detailed fabric texture:\n{{ description }}\nWearing method: complete full-body outfit\n{{ extra_details }}\nImage requirements:\n- Ultra-high detail, 8k resolution, extreme sharpness and texture\n- Cinematic shallow or medium depth of field, f/1.8 to f/4, emphasizing costume texture\n- Professional fashion / cinematic costume photography style plus contemporary still-frame texture\n- Realistic fabric texture, stitching, buttons, metal accessories, wrinkles, and wear details clearly visible\n- Excellent composition with the costume as the main subject or occupying more than two-thirds of the image\n- Closely match the {{ visual_style }} visual language and the overall {{ style }} atmosphere with high style consistency\n\nNegative prompt (strong negatives):\nlow quality, worst quality, blurry, deformed, bad anatomy, bad hands, missing fingers, extra limbs, poorly drawn face, bad proportions, watermark, text, logo, signature, overexposed, underexposed, plastic skin, doll, lowres, jpeg artifacts, grainy\n{%- if "anime" in visual_style.lower() -%}\nbad anime, deformed anime, low quality anime, flat color, flat shading, 3d render, cgi\n{%- else -%}\ncartoon, 3d render, cgi, illustration, painting, sketch, anime\n{%- endif -%}', '["description", "extra_details", "visual_style", "style", "base_negative"]', '2026-03-17 16:30:00', '2026-03-30 16:00:00', 1, 1);
